void  sensor_enable( Sensor sensor  )
{
	sensor->status.is_disabled   = FALSE  ; 
	
	sensor->status.warning_na    = FALSE  ;
	sensor->status.trigger_na    = FALSE  ;
		
	npc_start( sensor->npc_trg  );
	
	npc_start( sensor->npc_warn );
}
